begin;
create table public.portfolio_risk_snapshots(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id)on delete cascade,portfolio_snapshot_id uuid not null references public.portfolio_snapshots(id),calculated_at timestamptz not null,methodology_version text not null,metrics jsonb not null,binding_constraints jsonb not null,warnings jsonb not null,unique(portfolio_snapshot_id,methodology_version));
create table public.allocation_protocols(id uuid primary key default gen_random_uuid(),version text not null unique,status text not null check(status in('FROZEN','RETIRED')),frozen_at timestamptz not null,eligible_assets text[]not null,policy_version text not null,benchmark_versions jsonb not null,rebalance_rule text not null,fees_bps numeric not null,slippage_bps numeric not null,kill_criteria jsonb not null,notes text not null);
insert into public.allocation_protocols(version,status,frozen_at,eligible_assets,policy_version,benchmark_versions,rebalance_rule,fees_bps,slippage_bps,kill_criteria,notes)values('cas-shadow-protocol-v1','FROZEN',now(),array['BTC','ETH','CASH'],'allocation-policy-v1-shadow.1','{"BTC_HOLD":"benchmark-v1","BTC_CASH_50_50":"benchmark-v1","BTC_ETH_60_40":"benchmark-v1","BTC_200DMA":"benchmark-v1"}','MONTHLY_OR_TARGET_BAND_BREACH',10,5,'{"criticalIntegrityDefects":0,"maximumMissingCycles":2,"minimumCashBreach":0,"sourceApprovalRequired":true,"minimumProspectiveMonths":6}','Precommitted before prospective allocation results. Changes require a new protocol.');
create table public.paper_portfolios(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id)on delete cascade,protocol_version text not null references public.allocation_protocols(version),base_currency text not null check(base_currency in('EUR','USD')),started_at timestamptz not null,status text not null check(status in('ACTIVE','FROZEN','COMPLETE')),initial_capital numeric not null check(initial_capital>0),unique(user_id,protocol_version));
create table public.paper_trades(id uuid primary key default gen_random_uuid(),paper_portfolio_id uuid not null references public.paper_portfolios(id),recommendation_id uuid not null references public.allocation_recommendations(id),asset text not null check(asset in('BTC','ETH','CASH')),side text not null check(side in('INCREASE','DECREASE')),quantity numeric not null,price numeric not null,fee numeric not null,slippage numeric not null,executed_at timestamptz not null,execution_rule text not null,unique(paper_portfolio_id,recommendation_id,asset));
create table public.paper_nav(id uuid primary key default gen_random_uuid(),paper_portfolio_id uuid not null references public.paper_portfolios(id),calculated_at timestamptz not null,nav numeric not null,positions jsonb not null,cash numeric not null,benchmark_nav jsonb not null,attribution jsonb not null,price_observation_ids uuid[]not null,calculation_version text not null,unique(paper_portfolio_id,calculated_at,calculation_version));
create table public.capital_readiness_assessments(id uuid primary key default gen_random_uuid(),assessed_at timestamptz not null,protocol_version text not null references public.allocation_protocols(version),status text not null check(status in('PASSED','BLOCKED')),gates jsonb not null,blockers jsonb not null,metrics jsonb not null);
create table public.asset_admission_reviews(id uuid primary key default gen_random_uuid(),symbol text not null,reviewed_at timestamptz not null,status text not null check(status in('ADMITTED','REJECTED','REVIEW_REQUIRED')),liquidity jsonb not null,custody jsonb not null,data_coverage jsonb not null,fundamental_model jsonb not null,exit_capacity jsonb not null,rationale text not null,unique(symbol,reviewed_at));
do $$declare t text;begin foreach t in array array['portfolio_risk_snapshots','allocation_protocols','paper_portfolios','paper_trades','paper_nav','capital_readiness_assessments','asset_admission_reviews']loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy "users read own risk"on public.portfolio_risk_snapshots for select to authenticated using((select auth.uid())=user_id);create policy "authenticated read allocation protocols"on public.allocation_protocols for select to authenticated using(true);create policy "users read own paper portfolios"on public.paper_portfolios for select to authenticated using((select auth.uid())=user_id);create policy "users read own paper trades"on public.paper_trades for select to authenticated using(exists(select 1 from public.paper_portfolios p where p.id=paper_portfolio_id and p.user_id=(select auth.uid())));create policy "users read own paper nav"on public.paper_nav for select to authenticated using(exists(select 1 from public.paper_portfolios p where p.id=paper_portfolio_id and p.user_id=(select auth.uid())));create policy "authenticated read readiness"on public.capital_readiness_assessments for select to authenticated using(true);create policy "authenticated read admission"on public.asset_admission_reviews for select to authenticated using(true);
commit;
